namespace JingFamily {
 public class FamilyTree:ScrollableControl {
  public string SelectedId="",FocusId="",Mode="全部成员";
  public DiagramOptions Options=new DiagramOptions();public LineageLayout LayoutData=new LineageLayout();
  public event Action<string> Picked,Edit;public event Action ViewChanged;
  public HashSet<string> Collapsed=new HashSet<string>();float zoom=1;Point dragStart,scrollStart;bool dragging=false,moved=false;ToolTip tip=new ToolTip();string hover="";
  public float ZoomValue {get{return zoom;}} public PointF ViewOffset {get{return new PointF(Math.Max(0,(ClientSize.Width-LayoutData.Size.Width*zoom)/2),Math.Max(0,(ClientSize.Height-LayoutData.Size.Height*zoom)/2));}}
  public FamilyTree(){DoubleBuffered=true;AutoScroll=true;BackColor=Ui.Cream;TabStop=true;MouseDown+=(s,e)=>{moved=false;Focus();if(e.Button==MouseButtons.Middle||(e.Button==MouseButtons.Left&&Hit(e.Location)=="")){dragging=true;moved=false;dragStart=e.Location;scrollStart=new Point(-AutoScrollPosition.X,-AutoScrollPosition.Y);Cursor=Cursors.SizeAll;}};MouseMove+=(s,e)=>{if(dragging){int dx=e.X-dragStart.X,dy=e.Y-dragStart.Y;if(Math.Abs(dx)+Math.Abs(dy)>3)moved=true;AutoScrollPosition=new Point(Math.Max(0,scrollStart.X-dx),Math.Max(0,scrollStart.Y-dy));return;}string id=Hit(e.Location);if(id!=hover){hover=id;var p=Store.Get(id);tip.SetToolTip(this,p==null?"拖动空白处平移；Ctrl + 滚轮缩放；双击成员编辑。":p.Name+"\n父亲："+Store.Name(p.FatherId)+"\n母亲："+Store.Name(p.MotherId)+"\n配偶："+String.Join("、",p.Spouses.Select(Store.Name))+"\n"+p.Place+" "+p.Occupation);}};MouseUp+=(s,e)=>{if(dragging){dragging=false;Cursor=Cursors.Default;}};MouseClick+=(s,e)=>{if(e.Button!=MouseButtons.Left||moved){moved=false;return;}string id=Hit(e.Location);if(id!=""){SelectedId=id;Invalidate();if(Picked!=null)Picked(id);}};MouseDoubleClick+=(s,e)=>{string id=Hit(e.Location);if(id!=""&&Edit!=null){SelectedId=id;Edit(id);}};var menu=new ContextMenuStrip();menu.Items.Add("以此人为中心看后代",null,(s,e)=>Branch("后代"));menu.Items.Add("以此人为中心看祖先",null,(s,e)=>Branch("祖先"));menu.Items.Add("收起 / 展开其后代",null,(s,e)=>ToggleBranch());menu.Items.Add("编辑此成员",null,(s,e)=>{if(Edit!=null&&SelectedId!="")Edit(SelectedId);});menu.Opening+=(s,e)=>{var local=PointToClient(Cursor.Position);string id=Hit(local);if(id!=""){SelectedId=id;Invalidate();if(Picked!=null)Picked(id);}if(SelectedId=="")e.Cancel=true;};ContextMenuStrip=menu;}
  protected override void Dispose(bool disposing){if(disposing)tip.Dispose();base.Dispose(disposing);}
  protected override void OnMouseWheel(MouseEventArgs e){if((ModifierKeys&Keys.Control)!=0){Zoom(e.Delta>0?1.15f:1/1.15f);return;}base.OnMouseWheel(e);}
  string Hit(Point pt){var p=new PointF((pt.X-AutoScrollPosition.X-ViewOffset.X)/zoom,(pt.Y-AutoScrollPosition.Y-ViewOffset.Y)/zoom);foreach(var pair in LayoutData.Boxes)if(pair.Value.Contains(p))return pair.Key;return "";}
  public void Branch(string mode){if(Store.Get(SelectedId)==null)return;FocusId=SelectedId;Mode=mode;Collapsed.Clear();Relayout();FitView();}
  public void ToggleBranch(){if(Store.Get(SelectedId)==null)return;if(!Collapsed.Add(SelectedId))Collapsed.Remove(SelectedId);Relayout();}
  public void ExpandAll(){Collapsed.Clear();Relayout();}
  public void Zoom(float factor){SetZoom(zoom*factor);}
  void SetZoom(float value){float old=zoom;float cx=(-AutoScrollPosition.X+ClientSize.Width/2f-ViewOffset.X)/old,cy=(-AutoScrollPosition.Y+ClientSize.Height/2f-ViewOffset.Y)/old;zoom=Math.Max(.08f,Math.Min(3f,value));Extent();AutoScrollPosition=new Point(Math.Max(0,(int)(cx*zoom+ViewOffset.X-ClientSize.Width/2f)),Math.Max(0,(int)(cy*zoom+ViewOffset.Y-ClientSize.Height/2f)));Invalidate();if(ViewChanged!=null)ViewChanged();}
  void Extent(){AutoScrollMinSize=new Size((int)Math.Ceiling(LayoutData.Size.Width*zoom),(int)Math.Ceiling(LayoutData.Size.Height*zoom));}
  public void ResetZoom(){SetZoom(1);AutoScrollPosition=Point.Empty;}
  public void FitView(){if(LayoutData.Size.Width<=0)return;SetZoom(Math.Min((ClientSize.Width-28)/LayoutData.Size.Width,(ClientSize.Height-28)/LayoutData.Size.Height));AutoScrollPosition=Point.Empty;}
  public bool CenterPerson(string id){RectangleF r;if(!LayoutData.Boxes.TryGetValue(id,out r))return false;SelectedId=id;AutoScrollPosition=new Point(Math.Max(0,(int)((r.X+r.Width/2)*zoom-ClientSize.Width/2)),Math.Max(0,(int)((r.Y+r.Height/2)*zoom-ClientSize.Height/2)));Invalidate();if(Picked!=null)Picked(id);return true;}
  public List<Person> VisiblePeople(){var all=Store.Data.People;var ids=new HashSet<string>();var focus=Store.Get(FocusId);if(Mode=="全部成员"||focus==null)foreach(var p in all)ids.Add(p.Id);else if(Mode=="近亲"){ids.Add(focus.Id);foreach(var p in all)if(p.Id==focus.FatherId||p.Id==focus.MotherId||focus.Spouses.Contains(p.Id)||p.FatherId==focus.Id||p.MotherId==focus.Id||((focus.FatherId!=""&&p.FatherId==focus.FatherId)||(focus.MotherId!=""&&p.MotherId==focus.MotherId)))ids.Add(p.Id);}else{var q=new Queue<Tuple<string,int>>();q.Enqueue(Tuple.Create(focus.Id,0));while(q.Count>0){var item=q.Dequeue();if(!ids.Add(item.Item1))continue;if(Options.Depth>0&&item.Item2>=Options.Depth)continue;var person=Store.Get(item.Item1);if(person==null)continue;IEnumerable<string> next=Mode=="祖先"?new[]{person.FatherId,person.MotherId}.Where(x=>x!=""):all.Where(x=>x.FatherId==person.Id||x.MotherId==person.Id).Select(x=>x.Id);foreach(string id in next)q.Enqueue(Tuple.Create(id,item.Item2+1));}}if(Options.IncludeSpouses&&Mode!="全部成员"){var extra=all.Where(p=>ids.Contains(p.Id)).SelectMany(p=>p.Spouses).ToArray();foreach(string id in extra)ids.Add(id);}if(Collapsed.Count>0){var hidden=new HashSet<string>();var q=new Queue<string>(Collapsed);while(q.Count>0){string parent=q.Dequeue();foreach(var child in all.Where(p=>p.FatherId==parent||p.MotherId==parent))if(hidden.Add(child.Id))q.Enqueue(child.Id);}ids.ExceptWith(hidden);}return all.Where(p=>ids.Contains(p.Id)).ToList();}
  public void Relayout(){BackColor=ColorTranslator.FromHtml(Palette.Get(Options.Theme).Background);LayoutData.Build(VisiblePeople(),Options);if(Mode=="全部成员"&&Options.Depth>0){var keep=LayoutData.People.Where(p=>LayoutData.Ranks[p.Id]<Options.Depth).ToList();LayoutData.Build(keep,Options);}Extent();Invalidate();if(ViewChanged!=null)ViewChanged();}
  protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);e.Graphics.TranslateTransform(AutoScrollPosition.X+ViewOffset.X,AutoScrollPosition.Y+ViewOffset.Y);e.Graphics.ScaleTransform(zoom,zoom);LayoutData.Draw(new DiagramCanvas(e.Graphics),Options,SelectedId,Collapsed);}
  public void ExportSvg(string path){Relayout();var c=new DiagramCanvas(LayoutData.Size.Width,LayoutData.Size.Height);LayoutData.Draw(c,Options,"",Collapsed);File.WriteAllText(path,c.Svg(),new UTF8Encoding(false));}
  public void ExportHtml(string path){Relayout();var c=new DiagramCanvas(LayoutData.Size.Width,LayoutData.Size.Height);LayoutData.Draw(c,Options,"",Collapsed);string svg=c.Svg();svg=svg.Substring(svg.IndexOf("<svg",StringComparison.Ordinal));string html="<!doctype html><html lang='zh-CN'><meta charset='utf-8'>"+BrandMark.HtmlHead()+"<meta name='viewport' content='width=device-width,initial-scale=1'><title>"+Store.X(Store.Data.Title)+" · 景·谱</title><style>*{box-sizing:border-box}body{margin:0;background:#edf0e7;font:14px 'Microsoft YaHei',sans-serif;color:#203f37}header{height:64px;display:flex;align-items:center;gap:10px;padding:12px 20px;background:#fffefa;border-bottom:1px solid #d8dfd3}button,input{font:inherit;border:1px solid #ccd8ca;border-radius:7px;background:white;padding:8px 12px;color:#203f37}button{cursor:pointer}main{height:calc(100vh - 64px);overflow:hidden}svg{display:block;width:100%;height:100%;touch-action:none;user-select:none}g.focus{filter:drop-shadow(0 0 5px #c69948)}small{color:#758277}@media print{header{display:none}main{height:100vh}svg{width:100%;height:100%}}</style><header>"+BrandMark.HtmlImage(34)+"<strong>景·谱 / 世系图</strong><input id='search' aria-label='查找成员' placeholder='输入姓名定位'><button id='find'>定位</button><button id='plus'>＋</button><button id='minus'>－</button><button id='fit'>全图</button><button id='print'>打印</button><small id='msg'>拖动平移 · 滚轮缩放 · 成员悬停查看信息</small></header><main>"+svg+"</main><script>(function(){'use strict';const s=document.querySelector('svg'),initial=s.viewBox.baseVal;let original=[initial.x,initial.y,initial.width,initial.height],v=original.slice(),drag=null;const draw=()=>s.setAttribute('viewBox',v.join(' '));function zoom(k){let w=v[2]*k,h=v[3]*k;if(w<100||w>original[2]*8)return;v=[v[0]+(v[2]-w)/2,v[1]+(v[3]-h)/2,w,h];draw()}document.getElementById('plus').onclick=()=>zoom(.8);document.getElementById('minus').onclick=()=>zoom(1.25);document.getElementById('fit').onclick=()=>{v=original.slice();draw()};document.getElementById('print').onclick=()=>window.print();s.addEventListener('wheel',e=>{e.preventDefault();zoom(e.deltaY>0?1.15:.87)},{passive:false});s.onpointerdown=e=>{drag=[e.clientX,e.clientY,...v];s.setPointerCapture(e.pointerId)};s.onpointermove=e=>{if(!drag)return;const r=s.getBoundingClientRect(),scale=Math.max(drag[4]/r.width,drag[5]/r.height);v[0]=drag[2]-(e.clientX-drag[0])*scale;v[1]=drag[3]-(e.clientY-drag[1])*scale;draw()};s.onpointerup=()=>drag=null;s.onpointercancel=()=>drag=null;function find(){const q=document.getElementById('search').value.trim();if(!q)return;const nodes=Array.from(s.querySelectorAll('[data-person]')),node=nodes.find(n=>n.getAttribute('data-person')===q)||nodes.find(n=>n.getAttribute('data-person').includes(q));nodes.forEach(n=>n.classList.remove('focus'));document.getElementById('msg').textContent=node?'已定位：'+node.getAttribute('data-person'):'未找到该成员';if(node){node.classList.add('focus');const b=node.getBBox(),r=s.getBoundingClientRect(),w=Math.max(b.width*3,700),h=w*r.height/r.width;v=[b.x+b.width/2-w/2,b.y+b.height/2-h/2,w,h];draw()}}document.getElementById('find').onclick=find;document.getElementById('search').onkeydown=e=>{if(e.key==='Enter')find()};})();</script></html>";File.WriteAllText(path,html,new UTF8Encoding(false));}
  public void ExportPng(string path){ExportPng(path,1,false);}
  public void ExportPng(string path,float scale,bool transparent){Relayout();float w=LayoutData.Size.Width*scale,h=LayoutData.Size.Height*scale;if(w*h>64000000||w>24000||h>24000)throw new Exception("当前图谱过大，请缩小导出倍率、限制层数或切换分支；也可改用 SVG 矢量图。");using(var bmp=new Bitmap((int)Math.Ceiling(w),(int)Math.Ceiling(h),PixelFormat.Format32bppArgb)){using(var g=Graphics.FromImage(bmp)){g.ScaleTransform(scale,scale);LayoutData.Draw(new DiagramCanvas(g),Options,"",Collapsed,transparent);}bmp.Save(path,ImageFormat.Png);}}
  public void ExportEmf(string path){Relayout();using(var bmp=new Bitmap(1,1))using(var reference=Graphics.FromImage(bmp)){IntPtr hdc=reference.GetHdc();try{using(var meta=new Metafile(path,hdc,new RectangleF(0,0,LayoutData.Size.Width,LayoutData.Size.Height),MetafileFrameUnit.Pixel,EmfType.EmfPlusDual))using(var g=Graphics.FromImage(meta))LayoutData.Draw(new DiagramCanvas(g),Options,"",Collapsed);}finally{reference.ReleaseHdc(hdc);}}}
  public int PrintPageCount(bool tiled,Rectangle bounds){if(!tiled)return 1;return (int)Math.Ceiling(LayoutData.Size.Width/bounds.Width)*(int)Math.Ceiling(LayoutData.Size.Height/bounds.Height);}
  public void Print(){Print(false);}
  public void Print(bool tiled){Relayout();using(var pd=new PrintDocument()){pd.DocumentName=Store.Data.Title;pd.DefaultPageSettings.Landscape=true;int page=0;pd.BeginPrint+=(s,e)=>page=0;pd.PrintPage+=(s,e)=>{int cols=(int)Math.Ceiling(LayoutData.Size.Width/e.MarginBounds.Width);int total=PrintPageCount(tiled,e.MarginBounds);if(total>200){e.Cancel=true;throw new Exception("原尺寸分页超过 200 页，请限制层数或改用整图打印。");}e.Graphics.SetClip(e.MarginBounds);e.Graphics.TranslateTransform(e.MarginBounds.X,e.MarginBounds.Y);if(tiled){e.Graphics.TranslateTransform(-(page%cols)*e.MarginBounds.Width,-(page/cols)*e.MarginBounds.Height);}else{float scale=Math.Min(e.MarginBounds.Width/LayoutData.Size.Width,e.MarginBounds.Height/LayoutData.Size.Height);e.Graphics.ScaleTransform(scale,scale);}LayoutData.Draw(new DiagramCanvas(e.Graphics),Options,"",Collapsed);page++;e.HasMorePages=page<total;};using(var dlg=new PrintDialog{Document=pd,UseEXDialog=true,AllowSomePages=false})if(dlg.ShowDialog()==DialogResult.OK)pd.Print();}}
 }
 public class DiagramSettings:Editor {
  DiagramOptions options;ComboBox theme,depth;CheckBox compact,dates,place,job,generation,photos,spouses,bands;
  CheckBox Option(string label,bool value){var c=new CheckBox{Text=label,Checked=value};Field("显示设置",c);return c;}
  public DiagramSettings(DiagramOptions o):base("图谱样式与内容",690,730){options=o;theme=new ComboBox{DropDownStyle=ComboBoxStyle.DropDownList};theme.Items.AddRange(new[]{"玉笺 · 绿金","黛青 · 深色","墨印 · 黑白"});theme.SelectedIndex=o.Theme;Field("图谱主题",theme);depth=new ComboBox{DropDownStyle=ComboBoxStyle.DropDownList};depth.Items.Add("不限制");for(int i=1;i<=8;i++)depth.Items.Add(i+" 层 / 代范围");depth.SelectedIndex=o.Depth;Field("显示范围",depth);compact=Option("紧凑卡片（关闭则显示详细卡片）",o.Compact);dates=Option("生卒日期",o.ShowDates);place=Option("籍贯",o.ShowPlace);job=Option("职业",o.ShowJob);generation=Option("字辈",o.ShowGeneration);photos=Option("显示档案照片（导出时会内嵌照片）",o.ShowPhotos);spouses=Option("分支视图包含配偶",o.IncludeSpouses);bands=Option("分代背景与层级编号",o.ShowBands);Field("范围说明",Ui.Label("全部视图按相对层级截取；祖先/后代按亲子距离限制。\n照片为位图；关闭照片时 SVG / EMF 的图形文字为矢量。",9),65);}
  protected override bool Commit(){options.Theme=theme.SelectedIndex;options.Depth=depth.SelectedIndex;options.Compact=compact.Checked;options.ShowDates=dates.Checked;options.ShowPlace=place.Checked;options.ShowJob=job.Checked;options.ShowGeneration=generation.Checked;options.ShowPhotos=photos.Checked;options.IncludeSpouses=spouses.Checked;options.ShowBands=bands.Checked;return true;}
 }
 public class DiagramPage:UserControl {
  FamilyTree tree;ComboBox pick,mode;Label info;bool sync=false;Action<string> edit;
  public DiagramPage(string selected,Action<string> editMember,DiagramOptions options=null,Action<string> selection=null){edit=editMember;Dock=DockStyle.Fill;BackColor=Ui.Cream;Font=Ui.Font();var controls=new FlowLayoutPanel{Dock=DockStyle.Top,AutoSize=true,WrapContents=true,Padding=new Padding(0,6,0,0)};pick=new ComboBox{Width=205,DropDownStyle=ComboBoxStyle.DropDown,AutoCompleteMode=AutoCompleteMode.SuggestAppend,AutoCompleteSource=AutoCompleteSource.ListItems,Margin=new Padding(0,5,9,0)};pick.Items.Add(new PickItem("","输入姓名或选择成员"));foreach(var p in Store.Data.People)pick.Items.Add(new PickItem(p.Id,p.Name+" · "+p.Birth+" ["+p.Id.Substring(0,Math.Min(6,p.Id.Length))+"]"));pick.SelectedIndex=0;mode=new ComboBox{Width=105,DropDownStyle=ComboBoxStyle.DropDownList,Margin=new Padding(0,5,9,0)};mode.Items.AddRange(new[]{"全部成员","祖先","后代","近亲"});mode.SelectedIndex=0;controls.Controls.Add(new InputFrame(pick){Width=230,Height=39,Margin=new Padding(0,0,9,8)});controls.Controls.Add(new InputFrame(mode){Width=138,Height=39,Margin=new Padding(0,0,9,8)});controls.Controls.Add(Ui.Button("定位",()=>{string id=PickId();if(!tree.CenterPerson(id))Ui.Info("该成员未在当前视图中。请选择全部成员、展开分支或调整层数。");}));controls.Controls.Add(Ui.Button("样式 / 内容",()=>{using(var dlg=new DiagramSettings(tree.Options))if(dlg.ShowDialog(this)==DialogResult.OK){tree.Relayout();tree.FitView();}},true));controls.Controls.Add(Ui.Button("适合窗口",()=>tree.FitView()));controls.Controls.Add(Ui.Button("＋",()=>tree.Zoom(1.2f)));controls.Controls.Add(Ui.Button("－",()=>tree.Zoom(1/1.2f)));controls.Controls.Add(Ui.Button("100%",()=>tree.ResetZoom()));controls.Controls.Add(Ui.Button("收起 / 展开",()=>tree.ToggleBranch()));controls.Controls.Add(Ui.Button("展开全部",()=>tree.ExpandAll()));controls.Controls.Add(Ui.Button("导出 SVG",()=>Save("SVG 矢量图|*.svg","世系图.svg",tree.ExportSvg),true));controls.Controls.Add(Ui.Button("导出 EMF",()=>Save("EMF 矢量图|*.emf","世系图.emf",tree.ExportEmf)));controls.Controls.Add(Ui.Button("交互网页",()=>Save("HTML 交互图谱|*.html","世系图-交互.html",tree.ExportHtml)));controls.Controls.Add(Ui.Button("高清 PNG",()=>Save("PNG 图片|*.png","世系图-2倍.png",f=>tree.ExportPng(f,2,false))));controls.Controls.Add(Ui.Button("透明 PNG",()=>Save("PNG 图片|*.png","世系图-透明.png",f=>tree.ExportPng(f,1,true))));controls.Controls.Add(Ui.Button("打印 / PDF",()=>tree.Print()));controls.Controls.Add(Ui.Button("分页打印",()=>tree.Print(true)));Controls.Add(controls);info=new Label{Dock=DockStyle.Bottom,Height=33,Font=Ui.Font(8.5f),ForeColor=Color.Gray,TextAlign=ContentAlignment.MiddleLeft};Controls.Add(info);tree=new FamilyTree{Dock=DockStyle.Fill,SelectedId=selected,Options=options??new DiagramOptions()};Controls.Add(tree);tree.BringToFront();tree.Picked+=id=>{if(selection!=null)selection(id);UpdateInfo();};tree.Edit+=id=>edit(id);tree.ViewChanged+=()=>{if(!sync){sync=true;mode.SelectedItem=tree.Mode;var focused=pick.Items.Cast<PickItem>().FirstOrDefault(x=>x.Id==tree.FocusId);if(focused!=null&&focused.Id!="")pick.SelectedItem=focused;sync=false;}UpdateInfo();};pick.SelectionChangeCommitted+=(s,e)=>Apply();mode.SelectedIndexChanged+=(s,e)=>{if(!sync)Apply();};tree.Relayout();ShownFit();}
  void ShownFit(){bool first=true;tree.SizeChanged+=(s,e)=>{if(first&&tree.Width>300&&tree.Height>200){first=false;tree.FitView();}};}
  string PickId(){var selected=pick.SelectedItem as PickItem;if(selected!=null&&selected.Id!="")return selected.Id;var matches=Store.Data.People.Where(p=>p.Name==pick.Text.Trim()).ToList();if(matches.Count==1)return matches[0].Id;throw new Exception("请选择下拉列表中的成员，同名成员可按出生日期和编号区分。");}
  void Apply(){try{if(mode.SelectedIndex>0){tree.FocusId=PickId();}else{var item=pick.SelectedItem as PickItem;tree.FocusId=item==null?"":item.Id;}tree.Mode=mode.Text;tree.Collapsed.Clear();tree.Relayout();tree.FitView();}catch(Exception ex){sync=true;mode.SelectedItem=tree.Mode;sync=false;Ui.Error(ex);}}
  void UpdateInfo(){if(tree==null)return;info.Text="当前 "+tree.LayoutData.People.Count+" 人 · "+tree.LayoutData.Layers+" 层 · "+Math.Round(tree.ZoomValue*100)+"%  |  "+(tree.SelectedId==""?"点击成员选择":Store.Name(tree.SelectedId))+"  |  双击编辑 · 右键分支 · 拖动空白平移 · Ctrl+滚轮缩放";}
  void Save(string filter,string name,Action<string> writer){string f=Ui.SavePath(filter,name);if(f!=null){writer(f);Ui.Info("已导出当前视图：\n"+f+"\n\nSVG 可在浏览器及支持 SVG 的矢量设计软件中打开。");}}
 }
